{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Plan & Pricing — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8f6f2;--card:#fff;--muted:#6b6b6b;--accent:#7aa37a;--accent-2:#a86c9b;--glass: rgba(255,255,255,0.6);--mono: 'Segoe UI', Roboto, Arial, sans-serif}
    html,body{height:100%;margin:0;font-family:var(--mono);background:linear-gradient(180deg,#fbfaf8 0%,#f2efe9 100%);color:#222}
    .site{min-height:100vh;display:flex;flex-direction:column}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:transparent}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:56px;height:56px;border-radius:12px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin:0 8px;color:#333;text-decoration:none;font-size:14px}
    main{flex:1}
    .hero{display:grid;grid-template-columns:1fr 380px;gap:28px;padding:36px 28px}
    .hero-card{background:var(--card);padding:28px;border-radius:14px;box-shadow:0 8px 30px rgba(20,20,20,0.06)}
    .hero h1{margin:0 0 8px;font-size:22px}
    .hero p{margin:0;color:var(--muted)}
    .pattern-spot{width:100%;height:100%;background-image:url('assets/img/pattern.svg');background-repeat:no-repeat;background-position:right top;background-size:260px}

    /* Pricing comparator */
    .pricing-wrap{display:flex;gap:18px;align-items:flex-start;margin-top:18px}
    .toggle{background:linear-gradient(180deg,#fff,#f5f5f5);padding:8px;border-radius:999px;display:inline-flex;align-items:center;gap:6px;border:1px solid rgba(10,10,10,0.04)}
    .toggle button{background:transparent;border:0;padding:6px 12px;border-radius:999px;cursor:pointer}
    .toggle .active{background:var(--accent);color:#fff}
    .plans{display:flex;gap:12px}
    .plan{background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--glass));padding:18px;border-radius:12px;min-width:210px;border:1px solid rgba(10,10,10,0.04)}
    .plan h3{margin:0 0 8px;font-size:16px}
    .price{font-size:28px;font-weight:700;color:var(--accent);display:flex;align-items:baseline;gap:8px}
    .small{font-size:12px;color:var(--muted)}

    /* Mood selector */
    .mood{background:transparent;padding:20px;border-radius:12px;border:1px dashed rgba(120,120,120,0.08);display:flex;gap:10px;align-items:center;margin-top:18px}
    .mood button{background:#fff;border:1px solid rgba(10,10,10,0.04);padding:10px 12px;border-radius:8px;cursor:pointer}
    .mood button.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff;border-color:transparent}
    .method{margin-top:20px;padding:18px;background:var(--card);border-radius:12px;border-left:6px solid var(--accent);}
    .method h4{margin:0 0 6px}
    .cta{display:flex;gap:12px;margin-top:14px}
    .btn{padding:10px 14px;border-radius:10px;border:0;cursor:pointer}
    .btn-primary{background:var(--accent);color:#fff}
    .btn-outline{background:transparent;border:1px solid rgba(10,10,10,0.06);color:#333}

    footer{padding:28px;text-align:center;color:var(--muted);font-size:13px}

    /* Animations */
    .fade{transition:all 320ms ease}
    .pop{transform-origin:center;transition:transform 320ms cubic-bezier(.2,.9,.3,1)}

    @media(max-width:880px){
      .hero{grid-template-columns:1fr;}
      .pattern-spot{display:none}
      .plans{flex-direction:column}
    }
  </style>
</head>
<body>
<div class="site">
  <header>
    <div class="brand">
      <div class="logo">A</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Aroma care that moves with your day — may support calm & focus</div>
      </div>
    </div>
    <nav aria-label="Primary">
      <a href="index.html">Welcome</a>
      <a href="services.html">What I Do</a>
      <a href="blends.html">Blends & Kits</a>
      <a href="shop.html">Aromas</a>
      <a href="pricing.html">Plan</a>
      <a href="about.html">About</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="hero-card">
        <h1>Flexible ways to bring scent into your days</h1>
        <p>Choose a pace that suits your routine. Options below are framed to make scent approachable — each offering may support short pauses, focused minutes, or restful evenings.</p>

        <div class="pricing-wrap">
          <div>
            <div style="font-size:13px;color:var(--muted)">View pricing</div>
            <div class="toggle" role="tablist" aria-label="Billing cadence">
              <button id="cad-month" class="active" role="tab" aria-selected="true">Monthly</button>
              <button id="cad-pack" role="tab" aria-selected="false">Package</button>
            </div>
          </div>

          <div class="plans" id="plans">
            <div class="plan" data-month="19" data-pack="95">
              <h3>Intro Box</h3>
              <div class="price"><span class="num">$19</span><span class="small">/month</span></div>
              <div class="small">A curated trio of small blends + usage notes</div>
            </div>
            <div class="plan" data-month="45" data-pack="225">
              <h3>Balance Kit</h3>
              <div class="price"><span class="num">$45</span><span class="small">/month</span></div>
              <div class="small">Larger blends, ritual prompts, and refill options</div>
            </div>
            <div class="plan" data-month="85" data-pack="420">
              <h3>Support Package</h3>
              <div class="price"><span class="num">$85</span><span class="small">/month</span></div>
              <div class="small">Personal blend + two guided sessions (may support clarity)</div>
            </div>
          </div>
        </div>

        <div class="mood" aria-label="Mood to Method">
          <div style="font-size:13px;color:var(--muted);min-width:120px">How are you feeling?</div>
          <div style="display:flex;gap:8px;flex-wrap:wrap">
            <button class="mood-btn active" data-key="grounded">Grounded</button>
            <button class="mood-btn" data-key="stressed">Stressed</button>
            <button class="mood-btn" data-key="sleepy">Sleepy</button>
            <button class="mood-btn" data-key="focus">Need focus</button>
            <button class="mood-btn" data-key="joy">Brighten</button>
          </div>
        </div>

        <div class="method fade pop" id="method">
          <h4 id="method-title">Grounded Ritual</h4>
          <p id="method-desc">Gentle grounding blend suggestions with slow breathing prompts — a small ritual to root a busy moment. May support a steadier nervous system.</p>
          <div class="cta">
            <button id="primary-cta" class="btn btn-primary">Start a trial</button>
            <button class="btn btn-outline" id="learn-more">See details</button>
          </div>
        </div>

      </div>

      <div class="pattern-spot">
        <div style="padding:24px">
          <svg width="100%" height="100" viewBox="0 0 240 160" xmlns="http://www.w3.org/2000/svg" aria-hidden>
            <defs>
              <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#aee2b9"/><stop offset="1" stop-color="#caa3d7"/></linearGradient>
            </defs>
            <rect x="0" y="0" width="240" height="160" fill="url(#g1)" opacity="0.08" rx="12"/>
            <g fill="none" stroke="#fff" stroke-opacity="0.6">
              <path d="M12 40c30-24 60 20 100 8 24-8 40-36 70-10" stroke-width="1.2"/>
              <path d="M10 80c30-28 60 18 100 6 24-8 40-36 70-10" stroke-width="1"/>
              <circle cx="40" cy="30" r="4" fill="#fff" opacity="0.9"/>
            </g>
          </svg>
          <div style="margin-top:16px;font-size:13px;color:var(--muted)">Add-ons: roller blends, linen sprays, or guided mini-sessions available.</div>
        </div>
      </div>
    </section>

    <section style="padding:18px 28px">
      <div class="hero-card">
        <h3 style="margin-top:0">Pricing notes & safety</h3>
        <ul style="color:var(--muted)">
          <li>All products include dilution guidance and recommended holding ratios — follow patch test suggestions before full use.</li>
          <li>Pregnant or nursing? Consult your care provider before trying new essential oils; some oils are not recommended in pregnancy.</li>
          <li>If you have pets, check safety notes — some essential oils may affect animals; keep oils out of reach and well-diluted.</li>
        </ul>
      </div>
    </section>

  </main>

  <footer>
    <div>{{BUSINESS_NAME}} — Reach us at <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    <div style="margin-top:6px">Serving {{CITY}}, {{STATE}} • © <span id="year"></span></div>
  </footer>
</div>

<script>
  document.getElementById('year').textContent = new Date().getFullYear();

  // Pricing comparator
  const cadMonth = document.getElementById('cad-month');
  const cadPack = document.getElementById('cad-pack');
  const plans = Array.from(document.querySelectorAll('.plan'));

  function animateNumber(el, start, end){
    const duration = 420;
    const startTime = performance.now();
    function tick(now){
      const t = Math.min(1,(now-startTime)/duration);
      const ease = (--t)*t*t+1; // easeOut
      const val = Math.round(start + (end-start)*ease);
      el.textContent = '$' + val;
      if(Math.abs(val-end) > 0.5) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }

  cadMonth.addEventListener('click', ()=>{
    cadMonth.classList.add('active'); cadPack.classList.remove('active');
    cadMonth.setAttribute('aria-selected','true'); cadPack.setAttribute('aria-selected','false');
    plans.forEach(p=>{
      const target = parseInt(p.getAttribute('data-month'),10);
      const num = p.querySelector('.num');
      const current = parseInt(num.textContent.replace(/[^0-9]/g,''),10)||0;
      num.classList.add('pop');
      animateNumber(num,current,target);
      setTimeout(()=>num.classList.remove('pop'),420);
      p.querySelector('.small').textContent = '/month';
    });
  });

  cadPack.addEventListener('click', ()=>{
    cadPack.classList.add('active'); cadMonth.classList.remove('active');
    cadPack.setAttribute('aria-selected','true'); cadMonth.setAttribute('aria-selected','false');
    plans.forEach(p=>{
      const target = parseInt(p.getAttribute('data-pack'),10);
      const num = p.querySelector('.num');
      const current = parseInt(num.textContent.replace(/[^0-9]/g,''),10)||0;
      num.classList.add('pop');
      animateNumber(num,current,target);
      setTimeout(()=>num.classList.remove('pop'),420);
      p.querySelector('.small').textContent = 'one-off';
    });
  });

  // Mood-to-Method
  const moodButtons = Array.from(document.querySelectorAll('.mood-btn'));
  const methodTitle = document.getElementById('method-title');
  const methodDesc = document.getElementById('method-desc');
  const primaryCta = document.getElementById('primary-cta');

  const methods = {
    'grounded':{
      title:'Grounded Ritual',
      desc:'Gentle grounding blend suggestions with slow breathing prompts — a small ritual to root a busy moment. May support a steadier nervous system.',
      cta:'Begin a grounding trial'
    },
    'stressed':{
      title:'Calm-Down Sequence',
      desc:'A blend + short breathwork pattern to ease a racing moment. Use as a short pause; may support calmer reactivity.',
      cta:'Try a calm-down set'
    },
    'sleepy':{
      title:'Quiet Evening Mix',
      desc:'A sleep-friendly blend and bedside ritual to cue rest. Includes dilution guidance and patch-test reminders.',
      cta:'Preview the evening mix'
    },
    'focus':{
      title:'Clarity Focus Kit',
      desc:'UAromatic combinations designed to support sustained attention for short windows of work. Includes safe inhalation tips.',
      cta:'Grab a focus kit'
    },
    'joy':{
      title:'Lift & Lighten',
      desc:'Bright, buoyant notes chosen to lift ambience and invite playful breathwork. May support brighter moments.',
      cta:'Choose a bright blend'
    }
  };

  function setMood(key){
    moodButtons.forEach(b=>b.classList.toggle('active', b.dataset.key===key));
    const d = methods[key];
    methodTitle.classList.add('fade');
    methodDesc.classList.add('fade');
    setTimeout(()=>{
      methodTitle.textContent = d.title;
      methodDesc.textContent = d.desc;
      primaryCta.textContent = d.cta;
      methodTitle.classList.remove('fade');
      methodDesc.classList.remove('fade');
    },180);
    // CTA URL update with friendly param
    primaryCta.onclick = ()=>{
      const url = new URL('{{PRIMARY_CTA_URL}}', window.location.href);
      url.searchParams.set('mood', key);
      window.location.href = url.toString();
    };
  }

  moodButtons.forEach(b=>{
    b.addEventListener('click', ()=> setMood(b.dataset.key));
  });

  // init
  setMood('grounded');

</script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff9f6;--accent:#7aa37a;--muted:#666;--card:#fff;--mono: 'Segoe UI', Roboto, Arial, sans-serif}
    body{margin:0;font-family:var(--mono);background:var(--bg);color:#222}
    .wrap{max-width:980px;margin:28px auto;padding:0 18px}
    header{display:flex;justify-content:space-between;align-items:center}
    .nav a{margin-left:10px;text-decoration:none;color:#333;font-size:14px}
    .hero{display:flex;gap:18px;align-items:flex-start;margin-top:22px}
    .profile{flex:1;background:var(--card);padding:20px;border-radius:12px;box-shadow:0 10px 30px rgba(10,10,10,0.04)}
    .profile h1{margin:0 0 6px}
    .story{color:var(--muted);line-height:1.5}
    .values{display:flex;gap:12px;margin-top:12px}
    .pill{background:linear-gradient(90deg,#fff,#f7f7f7);padding:8px 12px;border-radius:999px;font-size:13px;border:1px solid rgba(10,10,10,0.04)}

    .mood-panel{margin-top:18px;display:flex;gap:12px}
    .mood-ui{flex:1;padding:16px;border-radius:12px;background:linear-gradient(180deg,white,rgba(255,255,255,0.9));border-left:6px solid var(--accent)}
    .mood-ui h3{margin:0 0 6px}
    .mood-grid{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}
    .mood-grid button{padding:10px 12px;border-radius:8px;border:1px solid rgba(10,10,10,0.06);background:#fff;cursor:pointer}
    .mood-grid button.active{background:var(--accent);color:#fff}

    footer{margin-top:28px;color:var(--muted);font-size:13px;text-align:center}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="display:flex;align-items:center;gap:12px">
        <div style="width:56px;height:56px;border-radius:12px;background:linear-gradient(135deg,#a1d9a8,#c08cc9);display:flex;align-items:center;justify-content:center;color:white;font-weight:700">A</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">A gentle guide to scent-led practices</div>
        </div>
      </div>
      <nav class="nav">
        <a href="index.html">Welcome</a>
        <a href="services.html">Services</a>
        <a href="blends.html">Blends</a>
        <a href="pricing.html">Plan</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main>
      <section class="hero">
        <div class="profile">
          <h1>Hello — I'm the person behind the blends</h1>
          <p class="story">I started mixing scent for people after years of exploring how subtle aromas help mark a moment. My approach blends science-aware practice with creative smell craft. Sessions and products are designed to be safe, simple, and easy to add to the day. Everything shared here is intended to be supportive, not prescriptive, and always includes dilution and patch-test guidance.</p>

          <div class="values">
            <span class="pill">Safety-first guidance</span>
            <span class="pill">Plant-led blends</span>
            <span class="pill">Small rituals</span>
          </div>
        </div>

        <aside style="width:300px">
          <div style="padding:16px;border-radius:12px;background:linear-gradient(180deg,#fff,#fafafa);border:1px solid rgba(10,10,10,0.04)">
            <strong>Quick facts</strong>
            <div style="margin-top:10px;color:var(--muted)">
              Sessions are by appointment. Products ship with safe-use labels. If pregnant, nursing, or caring for pets, please check our safety notes.
            </div>
            <div style="margin-top:12px">
              <a class="pill" href="book.html" style="text-decoration:none;display:inline-block">Reserve a time</a>
            </div>
          </div>
        </aside>
      </section>

      <section class="mood-panel">
        <div class="mood-ui pop" id="mood-ui">
          <h3 id="mood-title">Pick a mood — see a simple approach</h3>
          <p id="mood-blurb">Choose one of the states below to get a short suggested method and a tailored next step. Safe use notes are included with each suggestion.</p>

          <div class="mood-grid" role="list">
            <button class="m-btn active" data-key="grounded">Grounded</button>
            <button class="m-btn" data-key="stressed">Stressed</button>
            <button class="m-btn" data-key="sleepy">Sleepy</button>
            <button class="m-btn" data-key="focus">Need focus</button>
            <button class="m-btn" data-key="joy">Light & bright</button>
          </div>

          <div style="display:flex;gap:8px;margin-top:12px">
            <button id="mood-cta" class="pill" style="cursor:pointer">Explore the method</button>
            <button onclick="location.href='contact.html'" class="pill" style="cursor:pointer">Ask a question</button>
          </div>
        </div>

        <div style="flex:1;padding:16px;background:linear-gradient(180deg,#fff,#fbfbfb);border-radius:12px;border:1px solid rgba(10,10,10,0.04)">
          <strong>Philosophy</strong>
          <p style="color:var(--muted);margin-top:8px">My work centers on translating aromatic complexity into moments you can use. I avoid grand claims and instead offer practices that may support clarity, calm, or restoration when used thoughtfully. Every offering includes dilution info and a patch test suggestion.</p>

          <details style="margin-top:10px">
            <summary style="cursor:pointer">Safety highlights</summary>
            <ul style="color:var(--muted)">
              <li>Patch test before extended use.</li>
              <li>Some oils are not for pregnancy or for close use around pets—see individual notes.</li>
              <li>When in doubt, dilute and use short inhalation windows.</li>
            </ul>
          </details>
        </div>
      </section>

    </main>

    <footer>
      <div style="margin-top:22px;color:var(--muted)">Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a> — Serving {{CITY}}, {{STATE}}</div>
    </footer>
  </div>

<script>
  // Mood-to-Method for About page (variation of the one on pricing)
  const moodButtons = Array.from(document.querySelectorAll('.m-btn'));
  const titleEl = document.getElementById('mood-title');
  const blurb = document.getElementById('mood-blurb');
  const moodCta = document.getElementById('mood-cta');

  const map = {
    'grounded':{title:'Gentle Grounding', blurb:'A slow inhalation pattern with an earthy blend. Dilute oils as directed and perform a patch test before skin contact.', cta:'Try a grounding suggestion'},
    'stressed':{title:'Short Calm Sequence', blurb:'A breath + scent mini, designed to be done standing or seated for under five minutes.', cta:'View calm sequence'},
    'sleepy':{title:'Evening Cue', blurb:'A bedside spritz routine with sleep-friendly ratio notes; avoid bright, stimulating oils at night.', cta:'See evening cues'},
    'focus':{title:'Focus Pairing', blurb:'A compact inhaler recipe and micro-break prompts to help anchor attention for short stretches.', cta:'Open focus pairing'},
    'joy':{title:'Brighten the room', blurb:'A colourful blend for shared spaces; use brief diffusion and respect pets' sensitivity.', cta:'Pick a brightening blend'}
  };

  function setMood(k){
    moodButtons.forEach(b=>b.classList.toggle('active', b.dataset.key===k));
    const m = map[k];
    titleEl.textContent = m.title;
    blurb.textContent = m.blurb;
    moodCta.textContent = m.cta;
    moodCta.onclick = ()=>{
      const u = new URL('{{PRIMARY_CTA_URL}}', window.location.href);
      u.searchParams.set('source','about');
      u.searchParams.set('mood',k);
      window.location.href = u.toString();
    };
  }

  moodButtons.forEach(b=>b.addEventListener('click', ()=> setMood(b.dataset.key)));
  setMood('grounded');
</script>
</body>
</html>"} 
