  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book a Session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f4fbf7;--accent:#a86c9b;--muted:#666;--card:#fff;--mono: 'Segoe UI', Roboto, Arial, sans-serif}
