<body>
  <div class="container">
    <header>
      <div style="display:flex;align-items:center;gap:12px">
        <div style="width:56px;height:56px;border-radius:12px;background:linear-gradient(135deg,#c9a3d6,#b7e6c9);display:flex;align-items:center;justify-content:center;color:white;font-weight:700">A</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">Book a short session or add a retail bundle</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Home</a>
