<script>
  // Mood-to-Method on booking with real-time CTA morph
  const moodBtns = Array.from(document.querySelectorAll('#mood-choices button'));
  const recTitle = document.getElementById('rec-title');
  const recDesc = document.getElementById('rec-desc');
  const bookBtn = document.getElementById('book-btn');

  const bookMap = {
    grounded:{title:'Grounded Ritual', desc:'Short grounding with earthy notes. Includes dilution & patch test reminders.', cta:'Reserve grounding slot'},
    stressed:{title:'Calm Mini', desc:'Quick calm sequence and inhaler suggestion. Use short inhalation windows; avoid direct skin contact without dilution.', cta:'Reserve a calm mini'},
    sleepy:{title:'Night Support', desc:'Evening blend and bedside ritual. Avoid stimulating oils near bedtime; patch test first.', cta:'Reserve sleep support'},
    focus:{title:'Focus Session', desc:'Blends and micro-practices for focused work sessions; includes safe inhalation guidance.', cta:'Reserve a focus session'},
    joy:{title:'Brighten Session', desc:'Uplifting notes for social spaces. Includes pet-safety reminders and dilution tips.', cta:'Reserve a brightening slot'}
  };

  function setBookingMood(key){
    moodBtns.forEach(b=>b.classList.toggle('active', b.dataset.key===key));
    const m = bookMap[key];
    recTitle.textContent = m.title;
    recDesc.textContent = m.desc;
    bookBtn.textContent = m.cta;
    bookBtn.onclick = ()=>{
      // simple client-side assemble and navigate to CTA with params
      const name = document.getElementById('name').value || 'guest';
      const url = new URL('{{PRIMARY_CTA_URL}}', window.location.href);
      url.searchParams.set('reserve','true');
      url.searchParams.set('mood',key);
      url.searchParams.set('name',name);
      // include chosen type
      url.searchParams.set('type', document.getElementById('type').value);
      // add-ons
      url.searchParams.set('roller', document.getElementById('add-roller').checked ? '1' : '0');
      window.location.href = url.toString();
    };
  }

  moodBtns.forEach(b=>b.addEventListener('click', ()=> setBookingMood(b.dataset.key)));
  setBookingMood('grounded');

  // Add-ons price preview
  const preview = document.getElementById('preview');
  const base = {mini:35, standard:65, blend:110};
  const checkIds = ['add-roller','add-spray','add-kit'];
  function updatePreview(){
    let sum = base[document.getElementById('type').value];
    if(document.getElementById('add-roller').checked) sum += 22;
    if(document.getElementById('add-spray').checked) sum += 18;
    if(document.getElementById('add-kit').checked) sum += 35;
    preview.textContent = '$' + sum + ' — estimated'
  }
  document.getElementById('type').addEventListener('change', updatePreview);
  checkIds.forEach(id=>document.getElementById(id).addEventListener('change', updatePreview));
  updatePreview();
</script>
